          <stop offset="1" stopColor="var(--color-navy-900)" />
        </linearGradient>
        <linearGradient id="ap-dach" x1="0" y1="1" x2="0.3" y2="0">
          <stop offset="0" stopColor="var(--color-navy-700)" />
