8:import { useTeilbarerZustand } from "@/components/Rechner/kontext";
9:import { ErgebnisKopf, MobilKurz, RechnerRahmen } from "@/components/Rechner/InvestTeile";
10:import { WEGE } from "./wege";
11:import { AGRI, ERLOESE, PACHT, REGIONEN } from "@/lib/invest/markt";
12:import { SYSTEME, agriVergleich, kulturById, systemPasst } from "@/lib/rechner/agriPv";
13:import { REGION_KURZ } from "@/lib/rechner/pacht";
14:import { fmt, fmtEur, fmtPct } from "@/lib/rechner/annahmen";
67:  return (
68:    <RechnerRahmen
